<script setup lang="ts">
/**
 * The numbered list of sources a reply cites (`design/components/source-list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/source-list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/source-list.module.css'

export interface CitationSource {
  title: string
  href: string
  domain?: string
  snippet?: string
}

export interface SourceListProps {
  /**
   * The list's accessible name, such as "Sources" in the app's language.
   */
  label: string
  /**
   * The sources in the order the reply numbers them, rendered as given and never sorted.
   */
  sources: CitationSource[]
}

defineOptions({ name: 'SourceList', inheritAttrs: false })

defineProps<SourceListProps>()
</script>

<template>
  <section
    v-if="sources.length > 0"
    :class="styles.root"
    :aria-label="label"
    data-member="source-list"
  >
    <!-- heading -->
    <span :class="styles.heading" aria-hidden="true">
      <Icon name="cite" size="sm" />
      {{ label }}
    </span>
    <!-- list -->
    <ol :class="styles.list">
      <template v-for="(source, position) in sources" :key="position">
        <!-- item -->
        <li :class="styles.item">
          <!-- index -->
          <span :class="styles.index" aria-hidden="true">
            {{ position + 1 }}
          </span>
          <!-- body -->
          <span :class="styles.body">
            <!-- title -->
            <a :class="styles.title" :href="source.href" target="_blank" rel="noreferrer">
              {{ source.title }}
              <span :class="styles.glyph">
                <Icon name="open-external" size="sm" />
              </span>
            </a>
            <!-- domain -->
            <span v-if="source.domain !== undefined" :class="styles.domain">
              {{ source.domain }}
            </span>
            <!-- snippet -->
            <span v-if="source.snippet !== undefined" :class="styles.snippet">
              {{ source.snippet }}
            </span>
          </span>
        </li>
      </template>
    </ol>
  </section>
</template>
